from taf.ul.sc.enb.generic_enb import GenericEnb


class AirScale(GenericEnb):
    def __init__(self,
                 fct,           # type: 'Fct'
                 fsps=None,     # type: 'Optional[List[Fsp]]'
                 ):

        self.fct = fct
        self.fsps = fsps

        super(AirScale, self).__init__(enb=fct, base_state='FCT')
